scwin.checkVal1 = function() {
	return WebSquare.wUnit.getDomById('gridView1_cell_0_0_text').value == '1234/56/78';
}
scwin.checkVal2 = function() {
	return window.checkVal2 == '##/##||####/##/##';
}
scwin.checkVal3 = function() {
	return WebSquare.wUnit.getDomById('gridView1_cell_1_0_text').value == '____/__/__';
}
scwin.checkVal4 = function() {
	return window.checkVal4 == '_';
}		

scwin.checkVal5 = function() {
	return WebSquare.wUnit.getDomById('gridView1_cell_0_1_text').value == '1234/56/78';
}
scwin.checkVal6 = function() {
	return window.checkVal6 == '####/##/##';
}
scwin.checkVal7 = function() {
	return WebSquare.wUnit.getDomById('gridView1_cell_1_1_text').value == '';
}
scwin.checkVal8 = function() {
	return window.checkVal8 == '';
}

scwin.checkVal9 = function() {
	return WebSquare.wUnit.getDomById('gridView1_cell_0_2_calendar_input').value == '2019/07/19';
}
scwin.checkVal10 = function() {
	return WebSquare.wUnit.getDomById('gridView1_cell_1_2_calendar_input').value == '____/__/__';
