}
scwin.checkVal14 = function() {
	return window.checkVal14 == '';
}		

scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1_').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger12').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()","true");
	WebSquare.wUnit.addCommand("pause", "500");			
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger13').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()","true");
	WebSquare.wUnit.addCommand("pause", "500");		

	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1_2').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()","true");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1_2_').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal6()","true");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger14').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal7()","true");
	WebSquare.wUnit.addCommand("pause", "500");			
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger15').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal8()","true");
	WebSquare.wUnit.addCommand("pause", "500");	

	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal9()","true");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger16').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal10()","true");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger17').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal11()","true");
	WebSquare.wUnit.addCommand("pause", "500");		

	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5_2').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal12()","true");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger18').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal13()","true");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger19').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal14()","true");
	WebSquare.wUnit.addCommand("pause", "500");				

	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
